mapper.update:
UPDATE password_reset_request SET status='APPROVED', code_hash=#{codeHash}, attempts=0,
       approved_by=#{admin}, approved_at=LOCALTIMESTAMP, expires_at=#{expiresAt}
WHERE id=#{id} AND status='PENDING'

UPDATE password_reset_request SET attempts=attempts+1,
       status=CASE WHEN attempts+1>=#{maxAttempts} THEN 'REJECTED' ELSE status END
WHERE id=#{id}
